import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Step 1: Build the graph and calculate in-degrees
    # adj: node -> list of nodes that depend on it
    # in_degree: node -> count of nodes it depends on
    adj = {}
    in_degree = {}

    # All unique nodes mentioned in the input
    all_nodes = set(deps.keys())
    for predecessors in deps.values():
        for node in predecessors:
            all_nodes.add(node)

    for node in all_nodes:
        adj[node] = []
        in_degree[node] = 0

    for node, predecessors in deps.items():
        for pred in predecessors:
            adj[pred].append(node)
            in_degree[node] += 1

    # Step 2: Use Kahn's algorithm with a priority queue for lexicographical order
    # Priority queue stores nodes with in-degree 0
    pq = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(pq)

    result = []
    while pq:
        u = heapq.heappop(pq)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # Step 3: Check for cycles
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result
