def eval_rpn(tokens: list[str]) -> int:
    stack = []
    for token in tokens:
        if token in ("+", "-", "*", "/"):
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                # Python's // operator floor divides (towards negative infinity).
                # The requirement is truncation towards zero.
                if a * b > 0:
                    stack.append(a // b)
                else:
                    stack.append(-(-a // b) if b != 0 else 0)
        else:
            stack.append(int(token))
    return stack[0]
