def calc(expr: str) -> float:
    import collections

    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit() or s[i] == '.':
                num_str = ""
                while i < len(s) and (s[i].isdigit() or s[i] == '.'):
                    num_str += s[i]
                    i += 1
                tokens.append(float(num_str))
                continue
            if s[i] in "+-*/()":
                tokens.append(s[i])
                i += 1
                continue
            i += 1
        return tokens

    tokens = tokenize(expr)

    def parse_expression(index):
        # Handles addition and subtraction (lowest precedence)
        left_val, next_index = parse_term(index)
        while next_index < len(tokens) and tokens[next_index] in ('+', '-'):
            op = tokens[next_index]
            right_val, next_index = parse_term(next_index + 1)
            if op == '+':
                left_val += right_val
            else:
                left_val -= right_val
        return left_val, next_index

    def parse_term(index):
        # Handles multiplication and division
        left_val, next_index = parse_factor(index)
        while next_index < len(tokens) and tokens[next_index] in ('*', '/'):
            op = tokens[next_index]
            right_val, next_index = parse_factor(next_index + 1)
            if op == '*':
                left_val *= right_val
            else:
                left_val /= right_val
        return left_val, next_index

    def parse_factor(index):
        # Handles unary minus and parentheses
        token = tokens[index]
        if token == '-':
            val, next_idx = parse_factor(index + 1)
            return -val, next_idx
        elif token == '(':
            val, next_idx = parse_expression(index + 1)
            # Skip the closing parenthesis
            return val, next_idx + 1
        else:
            return token, index + 1

    result, _ = parse_expression(0)
    return float(result)
