def edit_distance(a: str, b: str) -> int:
    rows = len(a) + 1
    cols = len(b) + 1

    # Create a DP table
    dp = [[0] * cols for _ in range(rows)]

    # Initialize base cases
    for i in range(rows):
        dp[i][0] = i
    for j in range(cols):
        dp[0][j] = j

    for i in range(1, rows):
        for j in range(1, cols):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1

            dp[i][j] = min(
                dp[i-1][j] + 1,      # deletion
                dp[i][j-1] + 1,      # insertion
                dp[i-1][j-1] + cost  # substitution
            )

    return dp[len(a)][len(b)]
