from collections import deque

class SlidingWindowLimiter:
    def __init__(self, limit: int, window: float):
        self.limit = limit
        self.window = window
        # Maps key to a deque of timestamps of successfully allowed requests
        self.history = {}

    def allow(self, key: str, now: float) -> bool:
        if key not in self.history:
            self.history[key] = deque()

        timestamps = self.history[key]

        # Remove timestamps that have fallen out of the sliding window
        # Interval is (now - window, now], so we remove timestamps <= now - window
        boundary = now - self.window
        while timestamps and timestamps[0] <= boundary:
            timestamps.popleft()

        if len(timestamps) < self.limit:
            timestamps.append(now)
            return True

        return False
