TIERS = [(100, 0.10), (300, 0.15), (float('inf'), 0.20)]

def bill(kwh: float) -> float:
    total = 0.0
    prev_limit = 0
    for limit, rate in TIERS:
        if kwh > prev_limit:
            # Calculate how many kWh fall into this specific tier
            applicable_kwh = min(kwh, limit) - prev_limit
            total += applicable_kwh * rate
            prev_limit = limit
        else:
            break
    return round(total, 2)
